mapper.select:
SELECT r.id, r.alarm_no, r.rule_id, r.instance_id, i.instance_name, i.host_ip, i.redis_port, r.metric_name, r.alarm_level, r.alarm_content, r.trigger_value, r.threshold, r.unit, r.trigger_time, r.recover_time, r.recover_status FROM alarm_record r LEFT JOIN redis_instance i ON r.instance_id = i.instance_id WHERE 1=1 AND r.instance_id = #{instanceId} AND r.alarm_level = #{alarmLevel} AND r.metric_key = #{metricKey} AND r.recover_status = #{recoverStatus}
AND (r.alarm_no LIKE CONCAT('%',#{keyword},'%') OR r.alarm_content LIKE CONCAT('%',#{keyword},'%'))
AND r.trigger_time BETWEEN #{startTime} AND #{endTime} ORDER BY r.trigger_time DESC

SELECT COUNT(*)
FROM alarm_record
WHERE rule_id = #{ruleId}
  AND instance_id = #{instanceId}
  AND trigger_time >= #{since}

SELECT r.alarm_no AS "alarmNo", r.metric_name AS "metricName", r.alarm_level AS "alarmLevel", r.alarm_content AS "alarmContent", r.trigger_value AS "triggerValue", r.threshold AS "threshold", r.unit AS "unit", r.trigger_time AS "triggerTime", r.recover_time AS "recoverTime", r.recover_status AS "recoverStatus", i.instance_name AS "instanceName" FROM alarm_record r LEFT JOIN redis_instance i ON r.instance_id = i.instance_id WHERE r.trigger_time BETWEEN #{startTime} AND #{endTime}
AND r.instance_id = #{instanceId}
ORDER BY r.trigger_time DESC LIMIT #{limit}

SELECT id, alarm_no, rule_id, instance_id, metric_key, metric_name, alarm_level, alarm_content, trigger_value, threshold, unit, trigger_time, recover_time, recover_status, created_time, updated_time FROM alarm_record WHERE recover_status = '0' AND rule_id IN
#{ruleId}
ORDER BY trigger_time ASC
